-- composition of rule kernels OrderBySubq x PropagateConst (sqlite), template graft_exists
CREATE VIEW n1 AS SELECT 7 AS c0 UNION SELECT 1 AS c0;
WITH cte1 AS (SELECT '{"k": -1, "a": [1, 2, 3]}' AS c0) SELECT CAST(5e-324 AS REAL) AS c0, 2 AS c1, (SELECT MIN (a2.c3) FROM (t4 AS a2 JOIN (SELECT * FROM t4 WHERE EXISTS (SELECT 1 FROM (WITH cte1 AS MATERIALIZED (SELECT MIN (CAST('abc' AS TEXT), CAST('ß' AS TEXT)) AS c0 FROM (SELECT FORMAT ('%s|%s', '{"k": 1, "a": [1, 2]}', '{}') AS c0, '2000-01-01 00:00:00' AS c1 FROM n1 AS a1 GROUP BY a1.c0) AS a2 WHERE TRUE GROUP BY a2.c1) SELECT 7 AS c0, (-42) AS c1, CAST(100 AS INTEGER) AS c2 FROM cte1 AS a3 WHERE FALSE) AS kb) OR NOT EXISTS (SELECT 1 FROM (WITH cte1 AS MATERIALIZED (SELECT MIN (CAST('abc' AS TEXT), CAST('ß' AS TEXT)) AS c0 FROM (SELECT FORMAT ('%s|%s', '{"k": 1, "a": [1, 2]}', '{}') AS c0, '2000-01-01 00:00:00' AS c1 FROM n1 AS a1 GROUP BY a1.c0) AS a2 WHERE TRUE GROUP BY a2.c1) SELECT 7 AS c0, (-42) AS c1, CAST(100 AS INTEGER) AS c2 FROM cte1 AS a3 WHERE FALSE) AS kb)) AS a3 ON (a2.c0 = a3.c0)) WHERE (a2.c0 = 10)) AS c2 FROM t0 AS a1 UNION SELECT CAST(0.5 AS REAL) AS c0, 16 AS c1, CAST(0.0 AS NUMERIC) AS c2;
